package com.bank.stream.service;

import com.bank.stream.model.WindowedEvent;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.logging.Logger;

// Aggregates per-minute counts with a moving watermark that bounds state.
public class WatermarkedAggregator {

    private static final Logger log = Logger.getLogger(WatermarkedAggregator.class.getName());

    private final int delayMinutes;
    private final Map<Integer, Long> windowState = new TreeMap<>(); // open-window counts
    private int maxEventMinute = Integer.MIN_VALUE;
    private long droppedLate = 0;

    public WatermarkedAggregator(int delayMinutes) {
        this.delayMinutes = delayMinutes;
    }

    // Process a batch of events: advance the watermark, drop late, clean state.
    public void process(List<WindowedEvent> batch) {
        for (WindowedEvent e : batch) {
            maxEventMinute = Math.max(maxEventMinute, e.getEventMinute());
        }
        int watermark = maxEventMinute - delayMinutes;

        for (WindowedEvent e : batch) {
            if (e.getEventMinute() < watermark) {
                droppedLate++;                                  // too late → dropped
                log.warning(() -> "Dropped late event in minute " + e.getEventMinute()
                        + " (watermark " + watermark + ")");
                continue;
            }
            windowState.merge(e.getEventMinute(), 1L, Long::sum);
        }
        // Clean up state for windows fully below the watermark.
        windowState.keySet().removeIf(minute -> minute < watermark);
        log.info(() -> "Watermark=" + watermark + " openWindows=" + windowState);
    }

    public Map<Integer, Long> getOpenWindows() { return new TreeMap<>(windowState); }
    public long getDroppedLate() { return droppedLate; }
}
