package com.bank.stream;

import com.bank.stream.model.WindowedEvent;
import com.bank.stream.service.WatermarkedAggregator;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: a moving watermark bounds state and drops too-late events.
public class WatermarkDemo {

    private static final Logger log = Logger.getLogger(WatermarkDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WatermarkedAggregator agg = new WatermarkedAggregator(10);

        // Batch 1: events around minute 60-62.
        agg.process(List.of(
            new WindowedEvent("SAV2001", 60),
            new WindowedEvent("CUR3001", 61),
            new WindowedEvent("SAV2001", 62)));

        // Batch 2: a fresh minute-75 event pushes the watermark to 65,
        // and a straggler from minute 50 is now too late.
        agg.process(List.of(
            new WindowedEvent("CUR3001", 75),
            new WindowedEvent("OLD0001", 50)));

        log.info(() -> "Final open windows: " + agg.getOpenWindows());
        log.info(() -> "Total dropped-late events: " + agg.getDroppedLate());
        log.info("Watermark demo complete.");
    }
}
